changeSet.sql:
ALTER TABLE app.StaffProfiles ADD CONSTRAINT FK_StaffProfiles_ReportingManager FOREIGN KEY (ReportingManagerUserId) REFERENCES app.Users (Id); ALTER TABLE app.StaffProfiles ADD CONSTRAINT CK_StaffProfiles_EmploymentType CHECK (EmploymentType IS NULL OR EmploymentType IN (N'FullTime', N'PartTime', N'Contract', N'Temporary', N'Intern'));
CREATE TABLE app.StaffBranchAccess ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, StaffProfileId UNIQUEIDENTIFIER NOT NULL, BranchId UNIQUEIDENTIFIER NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_StaffBranchAccess PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_StaffBranchAccess_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_StaffBranchAccess_StaffProfiles FOREIGN KEY (StaffProfileId) REFERENCES app.StaffProfiles (Id), CONSTRAINT FK_StaffBranchAccess_Branches FOREIGN KEY (BranchId) REFERENCES app.Branches (Id) ); CREATE UNIQUE INDEX UX_StaffBranchAccess_StaffProfileId_BranchId ON app.StaffBranchAccess (StaffProfileId, BranchId) WHERE DeletedAt IS NULL; CREATE INDEX IX_StaffBranchAccess_TenantId_StaffProfileId ON app.StaffBranchAccess (TenantId, StaffProfileId) WHERE DeletedAt IS NULL;
CREATE TABLE app.UserPermissionOverrides ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, UserId UNIQUEIDENTIFIER NOT NULL, PermissionId UNIQUEIDENTIFIER NOT NULL, Granted BIT NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_UserPermissionOverrides PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_UserPermissionOverrides_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_UserPermissionOverrides_Users FOREIGN KEY (UserId) REFERENCES app.Users (Id), CONSTRAINT FK_UserPermissionOverrides_Permissions FOREIGN KEY (PermissionId) REFERENCES app.Permissions (Id) ); CREATE UNIQUE INDEX UX_UserPermissionOverrides_TenantId_UserId_PermissionId ON app.UserPermissionOverrides (TenantId, UserId, PermissionId) WHERE DeletedAt IS NULL;
CREATE TABLE app.UserResourceScopes ( Id UNIQUEIDENTIFIER NOT NULL, TenantId UNIQUEIDENTIFIER NOT NULL, UserId UNIQUEIDENTIFIER NOT NULL, Resource NVARCHAR(64) NOT NULL, Scope NVARCHAR(32) NOT NULL, CreatedAt DATETIME2 NOT NULL, UpdatedAt DATETIME2 NOT NULL, DeletedAt DATETIME2 NULL, CreatedBy UNIQUEIDENTIFIER NULL, UpdatedBy UNIQUEIDENTIFIER NULL, RowVersion ROWVERSION NOT NULL, CONSTRAINT PK_UserResourceScopes PRIMARY KEY CLUSTERED (Id), CONSTRAINT FK_UserResourceScopes_Tenants FOREIGN KEY (TenantId) REFERENCES app.Tenants (Id), CONSTRAINT FK_UserResourceScopes_Users FOREIGN KEY (UserId) REFERENCES app.Users (Id), CONSTRAINT CK_UserResourceScopes_Scope CHECK (Scope IN (N'All', N'Branch', N'Assigned', N'Own')) ); CREATE UNIQUE INDEX UX_UserResourceScopes_TenantId_UserId_Resource ON app.UserResourceScopes (TenantId, UserId, Resource) WHERE DeletedAt IS NULL;
ALTER TABLE app.RoleResourceScopes DROP CONSTRAINT CK_RoleResourceScopes_Scope; ALTER TABLE app.RoleResourceScopes ADD CONSTRAINT CK_RoleResourceScopes_Scope CHECK (Scope IN (N'All', N'Branch', N'Assigned', N'Own'));

